  ],
  "residualConcerns": "Reported statistics are internally inconsistent (chi-square n = 10 and n = 77 for 7 athletes; SQ statistic printed as 'X2 = 3.15, p;'), already noted in limitations.",
  "spotCheckPriority": "normal"
 }
}

