{
 "paper": {
  "citation": "Varesco G, Yao CW, Dubé E, Simonelli G, Bieuzen F. The impact of long-haul travel and 13 h time change on sleep and rest activity circadian rhythm in speed skaters during World Cup competitions. Experimental Physiology. 2025;110(11):1732-1743.",
  "tldr": "Speed skaters travelling about 13 time zones slept less during travel and race days, then slept a little more each night in Asia until day 5. Race results were similar to other races that season, which suggests about five days of adjustment was enough for this team, though no control group was used.",
  "limitations": "Only 19 athletes from one team were studied, with no comparison group and actigraphy as the only sleep measure. Jumps were measured in 10 athletes, travel-day actigraphy was excluded, and no objective training load was recorded. The authors state they had seen race results before analysis, and the abstract reports P = 0.005 for the decline in sleep efficiency during the stay in Asia while the results and Table 2 report P = 0.017."
 },
 "verification": {
  "status": "CORRECTED",
  "changes": [
   "paper.citation: issue number missing -> added (11) ('1469445x, 2025, 11'); en dash in pages replaced with hyphen",
   "paper.tldr: 'so coaches can plan for roughly five days of adjustment' -> framed as what this uncontrolled study suggests",
   "paper.limitations: added abstract vs results conflict for sleep efficiency trend ('slight decrease in sleep efficiency (P = 0.005)' vs Table 2 'P = 0.017')"
  ],
  "residualConcerns": "",
  "spotCheckPriority": "normal"
 }
}

